//! Cross-language signing vectors generated by the real server code
//! (tests/vectors/gen_signing.py -> tests/vectors/signing.json).

use vigie_agent::sign::{sign, signing_string, Envelope};

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn load() -> serde_json::Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/vectors/signing.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

#[test]
fn rust_matches_python_signing_vectors() {
    let doc = load();
    let key = unhex(doc["key_hex"].as_str().unwrap());
    let vectors = doc["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 10);
    for v in vectors {
        let s = |k: &str| v[k].as_str().unwrap().to_string();
        let env = Envelope {
            collector_id: &s("collector_id"),
            key_id: &s("key_id"),
            boot_id: &s("boot_id"),
            seq: s("seq").parse().unwrap(),
            sent_ts: s("sent_ts").parse().unwrap(),
            batch_id: &s("batch_id"),
        };
        let body = unhex(&s("body_hex"));
        assert_eq!(
            String::from_utf8(signing_string(&env, &body)).unwrap(),
            s("signing_string"),
            "signing string: {}",
            s("name")
        );
        assert_eq!(
            sign(&key, &env, &body),
            s("signature"),
            "signature: {}",
            s("name")
        );
    }
}
